@Test
void testEstablishRouteViaProxyTunnelRetryOnAuthChallengePersistentConnection() throws Exception {
    final HttpRoute route = new HttpRoute(target, null, proxy, true);
    final HttpClientContext context = HttpClientContext.create();
    final ClassicHttpRequest request = new HttpGet("http://bar/test");
    final ClassicHttpResponse response1 = new BasicClassicHttpResponse(407, "Huh?");
    response1.setHeader(HttpHeaders.PROXY_AUTHENTICATE, StandardAuthScheme.BASIC + " realm=test");
    final InputStream inStream1 = Mockito.spy(new ByteArrayInputStream(new byte[] { 1, 2, 3 }));
    response1.setEntity(EntityBuilder.create().setStream(inStream1).build());
    final ClassicHttpResponse response2 = new BasicClassicHttpResponse(200, "OK");
    context.setCredentialsProvider(CredentialsProviderBuilder.create().add(new AuthScope(proxy), "user", "pass".toCharArray()).build());
    final ConnectionState connectionState = new ConnectionState();
    Mockito.doAnswer(connectionState.connectAnswer()).when(execRuntime).connectEndpoint(Mockito.any());
    Mockito.when(execRuntime.isEndpointConnected()).thenAnswer(connectionState.isConnectedAnswer());
    Mockito.when(reuseStrategy.keepAlive(Mockito.any(), Mockito.any(), Mockito.<HttpClientContext>any())).thenReturn(Boolean.TRUE);
    Mockito.when(execRuntime.execute(Mockito.anyString(), Mockito.any(), Mockito.any())).thenReturn(response1, response2);
    Mockito.when(proxyAuthStrategy.select(Mockito.eq(ChallengeType.PROXY), Mockito.any(), Mockito.any())).thenReturn(Collections.singletonList(new BasicScheme()));
    final ExecChain.Scope scope = new ExecChain.Scope("test", route, request, execRuntime, context);
    exec.execute(request, scope, execChain);
    Mockito.verify(execRuntime).connectEndpoint(context);
    Mockito.verify(inStream1).close();
}

