    final HttpRoute route = new HttpRoute(target);
    final HttpGet request = new HttpGet("/test");
    final HttpClientContext context = HttpClientContext.create();
    Mockito.mock(ClassicHttpResponse.class);
    Mockito.when(chain.proceed(Mockito.same(request), Mockito.any())).thenThrow(new IOException("Ka-boom"));
    Mockito.when(retryStrategy.retryRequest(Mockito.any(), Mockito.any(), Mockito.anyInt(), Mockito.any())).thenReturn(Boolean.TRUE, Boolean.FALSE);
    Mockito.when(retryStrategy.getRetryInterval(Mockito.any(), Mockito.any(), Mockito.anyInt(), Mockito.any())).thenReturn(nextInterval);
    Mockito.when(nextInterval.getDuration()).thenReturn(100L);
    Mockito.when(nextInterval.compareTo(Mockito.any())).thenReturn(-1);
    final ExecChain.Scope scope = new ExecChain.Scope("test", route, request, endpoint, context);
    retryExec.execute(request, scope, chain);
    Mockito.verify(chain, Mockito.times(2)).proceed(Mockito.any(), Mockito.same(scope));
    Mockito.verify(nextInterval, Mockito.times(1)).sleep();
}

@Test
void testAcquireEndpoint() throws Exception {
    final HttpClientContext context = HttpClientContext.create();
    @SuppressWarnings("deprecation")
    final RequestConfig config = RequestConfig.custom().setConnectionRequestTimeout(345, TimeUnit.MILLISECONDS).setConnectTimeout(123, TimeUnit.MILLISECONDS).build();
    context.setRequestConfig(config);
    final HttpRoute route = new HttpRoute(new HttpHost("host", 80));
    Mockito.when(mgr.lease(Mockito.eq("some-id"), Mockito.eq(route), Mockito.any(), Mockito.any())).thenReturn(leaseRequest);
    Mockito.when(leaseRequest.get(Mockito.any())).thenReturn(connectionEndpoint);
    execRuntime.acquireEndpoint("some-id", route, null, context);
    Assertions.assertTrue(execRuntime.isEndpointAcquired());
    Assertions.assertSame(connectionEndpoint, execRuntime.ensureValid());
    Assertions.assertFalse(execRuntime.isEndpointConnected());
    Assertions.assertFalse(execRuntime.isConnectionReusable());
    Mockito.verify(leaseRequest).get(Timeout.ofMilliseconds(345));
    Mockito.verify(cancellableDependency, Mockito.times(1)).setDependency(leaseRequest);
    Mockito.verify(cancellableDependency, Mockito.times(1)).setDependency(execRuntime);
    Mockito.verify(cancellableDependency, Mockito.times(2)).setDependency(Mockito.any());
}

