    Mockito.when(chain.proceed(HttpRequestMatcher.matchesRequestUri(uri1), ArgumentMatchers.any())).thenReturn(response2, response4);
    Mockito.when(chain.proceed(HttpRequestMatcher.matchesRequestUri(uri2), ArgumentMatchers.any())).thenReturn(response3);
    Mockito.when(httpRoutePlanner.determineRoute(ArgumentMatchers.eq(new HttpHost("localhost")), ArgumentMatchers.<HttpClientContext>any())).thenReturn(route);
