    final SecureRandom secureRandom = SecureRandom.getInstanceStrong();
    secureRandom.setSeed(System.currentTimeMillis());
    final StringBuilder buf = new StringBuilder();
    for (int i = 0; i < 16; i++) {
        buf.append(CHARS.charAt(secureRandom.nextInt(CHARS.length() - 1)));
    }
    final String token = buf.toString();
    configureServerWithBasicAuth(bootstrap -> bootstrap.register("*", AsyncEchoHandler::new).setExchangeHandlerDecorator(requestHandler -> new AuthenticatingAsyncDecorator(requestHandler, new BearerAuthenticationHandler(), new BasicTestAuthenticator(token, "test realm"))));
    final HttpHost target = startServer();
    final TestAsyncClient client = startClient();
    final CredentialsProvider credsProvider = Mockito.mock(CredentialsProvider.class);
    final HttpClientContext context1 = HttpClientContext.create();
    context1.setCredentialsProvider(credsProvider);
    final Future<SimpleHttpResponse> future1 = client.execute(SimpleRequestBuilder.get().setHttpHost(target).setPath("/").build(), context1, null);
    final SimpleHttpResponse response1 = future1.get();
    Assertions.assertNotNull(response1);
    Assertions.assertEquals(HttpStatus.SC_UNAUTHORIZED, response1.getCode());
    Mockito.verify(credsProvider).getCredentials(Mockito.eq(new AuthScope(target, "test realm", "bearer")), Mockito.any());
    final HttpClientContext context2 = HttpClientContext.create();
    Mockito.when(credsProvider.getCredentials(Mockito.any(), Mockito.any())).thenReturn(new BearerToken(token));
    context2.setCredentialsProvider(credsProvider);
    final Future<SimpleHttpResponse> future2 = client.execute(SimpleRequestBuilder.get().setHttpHost(target).setPath("/").build(), context2, null);
    final SimpleHttpResponse response2 = future2.get();
    Assertions.assertNotNull(response2);
