    final HttpClientContext context3 = HttpClientContext.create();
    Mockito.when(credsProvider.getCredentials(Mockito.any(), Mockito.any())).thenReturn(new BearerToken(token + "-expired"));
    context3.setCredentialsProvider(credsProvider);
    final Future<SimpleHttpResponse> future3 = client.execute(SimpleRequestBuilder.get().setHttpHost(target).setPath("/").build(), context3, null);
    final SimpleHttpResponse response3 = future3.get();
    Assertions.assertNotNull(response3);
    Assertions.assertEquals(HttpStatus.SC_UNAUTHORIZED, response3.getCode());
}

