    configureServerWithBasicAuth(bootstrap -> bootstrap.register("*", new EchoHandler()));
    final HttpHost target = startServer();
    final TestClient client = client();
    final HttpGet httpget = new HttpGet("/");
    final HttpClientContext context = HttpClientContext.create();
    final CredentialsProvider credsProvider = Mockito.mock(CredentialsProvider.class);
    Mockito.when(credsProvider.getCredentials(Mockito.any(), Mockito.any())).thenReturn(new UsernamePasswordCredentials("test", "test".toCharArray()));
    context.setCredentialsProvider(credsProvider);
    client.execute(target, httpget, context, response -> {
        final HttpEntity entity = response.getEntity();
        Assertions.assertEquals(HttpStatus.SC_OK, response.getCode());
        Assertions.assertNotNull(entity);
        EntityUtils.consume(entity);
        return null;
    });
    Mockito.verify(credsProvider).getCredentials(Mockito.eq(new AuthScope(target, "test realm", "basic")), Mockito.any());
}

